UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/bio-med-devices/ddoc063-blender-gallery-product-sheet.pdf',
  descripcion_larga_es = $d$El blender Bio-Med de bajo flujo con doble flujómetro de 0 a 15 lpm (ref. 2003FF15) integra dos puertos de salida que permiten alimentar dos terapias a la vez desde la misma mezcla, y se orienta a la UCI neonatal. En la serie 2003 de bajo flujo del catálogo Bio-Med el flujo total llega a 30 lpm, con purga de 3 lpm para flujos bajos.$d$,
  descripcion_larga_en = $d$The Bio-Med low-flow blender with dual 0 to 15 lpm flowmeters (ref. 2003FF15) integrates two output ports so two therapies can be fed from the same mix at once, and is aimed at the neonatal ICU. In the Bio-Med 2003 low-flow series the total flow reaches 30 lpm, with a 3 lpm bleed for low flows.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Bio-Med Devices, Inc."},{"clave":"Referencia","grupo":"Identificación","valor":"2003FF15"},{"clave":"Serie 2003FF (bajo flujo)","grupo":"Flujo","valor":"0 - 30 lpm; salidas con flujómetros de 0-15 lpm"},{"clave":"Purga","grupo":"Flujo","valor":"3 lpm para flujos < 3 lpm"},{"clave":"Salidas","grupo":"Puertos","valor":"2 puertos de salida"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Dos flujómetros y dos puertos de salida para alimentar dos terapias a la vez.","FiO₂ de 21 % a 100 % según la descripción del producto.","Serie de bajo flujo hasta 30 lpm de flujo total."],"beneficios_en":["Two flowmeters and two output ports to feed two therapies at once.","FiO₂ from 21% to 100% per the product description.","Low-flow series up to 30 lpm total flow."],"valor_es":"Un mezclador de aire y oxígeno de Bio-Med Devices con documentación oficial del fabricante.","valor_en":"An air/oxygen blender from Bio-Med Devices with official manufacturer documentation.","preguntas_frecuentes_es":[{"q":"¿Qué hace un blender de aire/oxígeno?","a":"Mezcla aire y oxígeno para entregar una FiO₂ definida de forma segura y precisa; el catálogo del fabricante lo presenta para terapia de oxígeno, CPAP de burbuja y alto flujo nasal."},{"q":"¿Dónde se fabrica?","a":"Bio-Med Devices lo fabrica en Guilford, Connecticut (EE. UU.), según el catálogo."},{"q":"¿Cuál es la diferencia entre las series de bajo y alto flujo?","a":"Las series de bajo flujo (2003) manejan 0-30 lpm; las de alto flujo (2002) llegan a 0-120 lpm, según el catálogo del fabricante."},{"q":"¿Dónde descargo la ficha técnica de Blender Serie Bajo Flujo Con Doble Flujómetro de 0 a 15 Ref 2003FF15 Bio-Med?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Bio-Med Devices (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What does an air/oxygen blender do?","a":"It mixes air and oxygen to deliver a defined FiO₂ safely and accurately; the manufacturer catalogue presents it for oxygen therapy, bubble CPAP and nasal high flow."},{"q":"Where is it made?","a":"Bio-Med Devices makes it in Guilford, Connecticut (USA), per the catalogue."},{"q":"What is the difference between low-flow and high-flow series?","a":"Low-flow series (2003) cover 0-30 lpm; high-flow series (2002) reach 0-120 lpm, per the manufacturer catalogue."},{"q":"Where can I download the Blender Low Flow Series with Dual Flowmeter 0-15 Ref 2003FF15 Bio-Med datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Bio-Med Devices PDF (in English)."}],"seo_keywords_es":["blender doble flujómetro","blender Bio-Med 2003FF15","mezclador de oxígeno UCI neonatal","blender neonatal bajo flujo","blender neonatal Colombia","catálogo Bio-Med blenders"],"seo_keywords_en":["dual flowmeter blender","Bio-Med 2003FF15 blender","neonatal ICU oxygen blender","low-flow neonatal blender","neonatal blender Colombia","Bio-Med blender catalogue"],"ficha_fabricante":{"fabricante":"Bio-Med Devices","idioma":"en","url_origen":"https://www.biomeddevices.com/s/DDOC063-Blender-Gallery-Product-Sheet.pdf","descargada":"2026-10-02"}}$j$::jsonb
