UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/bio-med-devices/ddoc063-blender-gallery-product-sheet.pdf',
  descripcion_larga_es = $d$El blender Bio-Med de alto flujo (denominado en el catálogo de I-ME con referencia 2002F70D y flujómetro de 0 a 30 lpm) mezcla aire y oxígeno de forma segura y precisa para oxigenoterapia de alto flujo. El catálogo Blender Gallery de Bio-Med Devices presenta la serie 2002 de alto flujo con rango de 0 a 120 lpm y precisión de FiO₂ de 15 a 120 lpm. Los datos exactos del flujómetro deben confirmarse por referencia al cotizar.$d$,
  descripcion_larga_en = $d$The Bio-Med high-flow blender (listed in the I-ME catalogue with ref. 2002F70D and a 0 to 30 lpm flowmeter) mixes air and oxygen safely and accurately for high-flow oxygen therapy. The Bio-Med Devices Blender Gallery catalogue presents the 2002 high-flow series with a 0 to 120 lpm range and FiO₂ accuracy from 15 to 120 lpm. Exact flowmeter data should be confirmed by reference when requesting a quote.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Bio-Med Devices, Inc."},{"clave":"Referencia","grupo":"Identificación","valor":"2002F70D (alto flujo)"},{"clave":"Rango de flujo (serie 2002)","grupo":"Flujo","valor":"0 - 120 lpm"},{"clave":"FiO₂","grupo":"Precisión","valor":"15 - 120 lpm"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Serie 2002 de alto flujo: rango de 0 a 120 lpm.","Precisión de FiO₂ declarada de 15 a 120 lpm.","Fabricado en EE. UU. por Bio-Med Devices."],"beneficios_en":["2002 high-flow series: 0 to 120 lpm range.","Stated FiO₂ accuracy from 15 to 120 lpm.","Made in the USA by Bio-Med Devices."],"valor_es":"Un mezclador de aire y oxígeno de Bio-Med Devices con documentación oficial del fabricante.","valor_en":"An air/oxygen blender from Bio-Med Devices with official manufacturer documentation.","preguntas_frecuentes_es":[{"q":"¿Qué hace un blender de aire/oxígeno?","a":"Mezcla aire y oxígeno para entregar una FiO₂ definida de forma segura y precisa; el catálogo del fabricante lo presenta para terapia de oxígeno, CPAP de burbuja y alto flujo nasal."},{"q":"¿Dónde se fabrica?","a":"Bio-Med Devices lo fabrica en Guilford, Connecticut (EE. UU.), según el catálogo."},{"q":"¿Cuál es la diferencia entre las series de bajo y alto flujo?","a":"Las series de bajo flujo (2003) manejan 0-30 lpm; las de alto flujo (2002) llegan a 0-120 lpm, según el catálogo del fabricante."},{"q":"¿Dónde descargo la ficha técnica de Blender Serie de Alto Flujo Con Flujómetro de 0 a 30Lpm Ref 2002F70D Bio-Med?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Bio-Med Devices (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What does an air/oxygen blender do?","a":"It mixes air and oxygen to deliver a defined FiO₂ safely and accurately; the manufacturer catalogue presents it for oxygen therapy, bubble CPAP and nasal high flow."},{"q":"Where is it made?","a":"Bio-Med Devices makes it in Guilford, Connecticut (USA), per the catalogue."},{"q":"What is the difference between low-flow and high-flow series?","a":"Low-flow series (2003) cover 0-30 lpm; high-flow series (2002) reach 0-120 lpm, per the manufacturer catalogue."},{"q":"Where can I download the BIO-MED High-Flow Series Blender with Flowmeter 0-30 Lpm Ref 2002F70D datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Bio-Med Devices PDF (in English)."}],"seo_keywords_es":["blender alto flujo","blender Bio-Med serie 2002","mezclador oxígeno alto flujo","oxigenoterapia de alto flujo","blender UCI Colombia","catálogo Bio-Med blenders"],"seo_keywords_en":["high-flow blender","Bio-Med 2002 series blender","high flow oxygen blender","high flow oxygen therapy","ICU blender Colombia","Bio-Med blender catalogue"],"ficha_fabricante":{"fabricante":"Bio-Med Devices","idioma":"en","url_origen":"https://www.biomeddevices.com/s/DDOC063-Blender-Gallery-Product-Sheet.pdf","descargada":"2026-10-02"}}$j$::jsonb
