UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/bio-med-devices/ddoc021-condensed-tv-100-4pg-product-sheet.pdf',
  descripcion_larga_es = $d$El TV-100 de Bio-Med Devices es un ventilador de transporte para pacientes neonatales, pediátricos y adultos que ofrece los modos y el desempeño de un ventilador de UCI en un diseño compacto. Incluye modo NIV (IPAP/EPAP), PRVC con garantía de volumen y HFNC/nCPAP (flujo de hasta 60 lpm para adultos). Tiene compresor interno, mezclador interno de oxígeno de 21 a 100 %, dos baterías recargables intercambiables en caliente con 7 a 11 horas de autonomía, y cumple la norma 60601-1-12 para servicios médicos de emergencia (IP44, vibración, 30 G y caídas desde 75 cm).$d$,
  descripcion_larga_en = $d$The Bio-Med Devices TV-100 is a transport ventilator for neonatal, paediatric and adult patients that offers the modes and performance of an ICU ventilator in a compact design. It includes NIV mode (IPAP/EPAP), PRVC with volume guarantee and HFNC/nCPAP (flow up to 60 lpm for adults). It has an internal compressor, an internal oxygen blender from 21 to 100%, two hot-swappable rechargeable batteries with 7 to 11 hours of runtime, and complies with the 60601-1-12 emergency medical services standard (IP44, vibration, 30 G and 75 cm drops).$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"TV-100"},{"clave":"Fabricante","grupo":"Identificación","valor":"Bio-Med Devices, Inc."},{"clave":"Rango","grupo":"Pacientes","valor":"Neonatal, pediátrico y adulto"},{"clave":"Modos","grupo":"Modos","valor":"NIV (IPAP/EPAP), PRVC, HFNC/nCPAP"},{"clave":"Oxígeno","grupo":"Gas","valor":"Mezclador interno 21 - 100 %; fuente de 50 psi"},{"clave":"Baterías","grupo":"Energía","valor":"2 recargables hot-swap; 7 a 11 h"},{"clave":"Transporte","grupo":"Normativa","valor":"60601-1-12; IP44; caída desde 75 cm"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Un solo ventilador para lactantes, niños y adultos, con modos NIV, PRVC y HFNC/nCPAP.","Compresor y mezclador de oxígeno internos (21-100 %): no requiere aire comprimido externo.","Dos baterías intercambiables en caliente con 7 a 11 horas y cumplimiento de la norma de transporte 60601-1-12."],"beneficios_en":["One ventilator for infants, children and adults, with NIV, PRVC and HFNC/nCPAP modes.","Internal compressor and oxygen blender (21-100%): no external compressed air needed.","Two hot-swappable batteries with 7 to 11 hours and compliance with transport standard 60601-1-12."],"valor_es":"Un ventilador de transporte compacto para neonatos, niños y adultos, con documentación oficial de Bio-Med Devices.","valor_en":"A compact transport ventilator for neonates, children and adults, with official Bio-Med Devices documentation.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes sirve?","a":"Desde los prematuros más pequeños hasta los adultos más grandes, según la hoja de producto."},{"q":"¿Qué autonomía tiene?","a":"De 7 a 11 horas de operación continua con las dos baterías cargadas, hot-swap."},{"q":"¿Qué modos incluye?","a":"NIV, PRVC con garantía de volumen y HFNC/nCPAP, entre otros descritos en la hoja de producto."},{"q":"¿Dónde descargo la ficha técnica de Ventilador Mecánico Neonatal Pediátrico Adulto Ref TV-100 Bio-Med?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Bio-Med Devices (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is it for?","a":"From the smallest premature infants to the largest adult patients, per the product sheet."},{"q":"What runtime does it have?","a":"7 to 11 hours of continuous operation with both batteries fully charged, hot-swappable."},{"q":"Which modes does it include?","a":"NIV, PRVC with volume guarantee and HFNC/nCPAP, among others described in the product sheet."},{"q":"Where can I download the Neonatal Pediatric Adult Mechanical Ventilator Ref TV-100 Bio-Med datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Bio-Med Devices PDF (in English)."}],"seo_keywords_es":["ventilador de transporte TV-100","ventilador neonatal pediátrico adulto","ventilador portátil Bio-Med","ventilador UCI de transporte","ventilador mecánico Colombia","ficha técnica TV-100"],"seo_keywords_en":["TV-100 transport ventilator","neonatal paediatric adult ventilator","Bio-Med portable ventilator","ICU transport ventilator","mechanical ventilator Colombia","TV-100 product sheet"],"ficha_fabricante":{"fabricante":"Bio-Med Devices","idioma":"en","url_origen":"https://www.biomeddevices.com/s/DDOC021-Condensed-TV-100-4pg-Product-Sheet.pdf","descargada":"2026-10-02"}}$j$::jsonb
