UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/bistos/catalog-bistos-bt-500-550-400-nicu.pdf',
  descripcion_larga_es = $d$La incubadora BT-500 de Bistos controla temperatura (aire 23-37 °C; piel 35-37,5 °C) y humedad (30-95 %), con doble pared y cortina de aire, ruido inferior a 45 dB, bandeja de rayos X y báscula integrada (0-10 kg), seis puertas de acceso y tanque de agua autoclavable de 1000 ml. Incluye pantalla TFT de 7", tendencias de 72 horas, 27 eventos de alarma, cámara CCD opcional, oximetría Masimo opcional y control de O₂ opcional. Mide 1354 x 1024 x 690 mm, pesa 99,3 kg y tiene 2 años de garantía.$d$,
  descripcion_larga_en = $d$The Bistos BT-500 incubator controls temperature (air 23-37 °C; skin 35-37.5 °C) and humidity (30-95%), with a double wall and air curtain, noise below 45 dB, X-ray tray and integrated scale (0-10 kg), six access doors and a 1000 ml autoclavable water tank. It includes a 7" TFT display, 72-hour trends, 27 alarm events, optional CCD camera, optional Masimo oximetry and optional O₂ control. It measures 1354 x 1024 x 690 mm, weighs 99.3 kg and has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"BT-500"},{"clave":"Fabricante","grupo":"Identificación","valor":"Bistos Co., Ltd."},{"clave":"Aire / piel","grupo":"Control térmico","valor":"23-37 °C / 35-37,5 °C"},{"clave":"Humedad","grupo":"Control térmico","valor":"30 - 95 %"},{"clave":"Ruido","grupo":"Acústica","valor":"< 45 dB"},{"clave":"Dimensiones / peso","grupo":"Dimensiones","valor":"1354 x 1024 x 690 mm; 99,3 kg"},{"clave":"Pantalla","grupo":"Pantalla","valor":"TFT de 7\" a color; tendencias de 72 h"},{"clave":"Garantía del fabricante","grupo":"Garantía","valor":"2 años (unidad principal)"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Doble pared con cortina de aire y ruido inferior a 45 dB para un entorno estable y silencioso.","Báscula (0-10 kg) y bandeja de rayos X integradas para evitar sacar al bebé de la incubadora.","Opcionales: oximetría Masimo, control de O₂, cámara CCD con transmisión Wi-Fi, soporte elevable y cesta."],"beneficios_en":["Double wall with air curtain and noise below 45 dB for a stable, quiet environment.","Integrated scale (0-10 kg) and X-ray tray to avoid removing the baby from the incubator.","Options: Masimo oximetry, O₂ control, CCD camera with Wi-Fi streaming, lifting stand and basket."],"valor_es":"Una incubadora de cuidado intensivo neonatal con control de temperatura y humedad y opcionales de SpO₂ y O₂, con catálogo oficial de Bistos.","valor_en":"An intensive-care neonatal incubator with temperature and humidity control and SpO₂ and O₂ options, with official Bistos catalogue.","preguntas_frecuentes_es":[{"q":"¿Qué rango de temperatura controla?","a":"Aire de 23 a 37 °C (override 37,1-39 °C) y piel de 35 a 37,5 °C (override 37,6-39 °C)."},{"q":"¿Qué dimensiones y peso tiene?","a":"1354 x 1024 x 690 mm y 99,3 kg en versión estándar."},{"q":"¿Qué garantía tiene?","a":"2 años en la unidad principal."},{"q":"¿Dónde descargo la ficha técnica de Incubadora de Cuidado Intensivo Ref BT-500 Bistos?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Bistos (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What temperature range does it control?","a":"Air from 23 to 37 °C (override 37.1-39 °C) and skin from 35 to 37.5 °C (override 37.6-39 °C)."},{"q":"What are its dimensions and weight?","a":"1354 x 1024 x 690 mm and 99.3 kg in the standard version."},{"q":"What warranty does it have?","a":"2 years on the main unit."},{"q":"Where can I download the Intensive Care Incubator Ref BT-500 Bistos datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Bistos PDF (in English)."}],"seo_keywords_es":["incubadora neonatal BT-500","incubadora de cuidado intensivo Bistos","incubadora con báscula integrada","incubadora para prematuros","incubadora neonatal Colombia","catálogo Bistos BT-500"],"seo_keywords_en":["BT-500 neonatal incubator","Bistos intensive care incubator","incubator with integrated scale","preterm incubator","neonatal incubator Colombia","Bistos BT-500 catalogue"],"ficha_fabricante":{"fabricante":"Bistos","idioma":"en","url_origen":"https://expertmedicalholding.com/wp-content/uploads/2020/11/Catalog_BISTOS_BT-500-550-400_NICU.pdf","descargada":"2026-10-02"}}$j$::jsonb
