UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/bistos/catalog-bistos-bt-500-550-400-nicu.pdf',
  descripcion_larga_es = $d$La lámpara de fototerapia BT-400 de Bistos usa LED azul con pico entre 450 y 475 nm, intensidad baja de 25-35 y alta de 35-55 µW/cm²/nm, vida útil de LED de hasta 100 000 horas, superficie efectiva de unos 40 x 20 cm a 40 cm y diseño sin ventilador (ruido < 30 dB). Muestra tiempo de tratamiento y de uso total en una pantalla TFT de 2,4", con temporizador de 30 min a 999 h. Cabezal de 3,6 kg (13 kg con carro) y 2 años de garantía.$d$,
  descripcion_larga_en = $d$The Bistos BT-400 phototherapy lamp uses blue LED with a peak between 450 and 475 nm, low intensity of 25-35 and high of 35-55 µW/cm²/nm, LED life of up to 100,000 hours, an effective surface of about 40 x 20 cm at 40 cm and a fan-less design (noise < 30 dB). It shows treatment time and total used time on a 2.4" TFT display, with a timer from 30 min to 999 h. The head weighs 3.6 kg (13 kg with cart) and has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"BT-400"},{"clave":"Fabricante","grupo":"Identificación","valor":"Bistos Co., Ltd."},{"clave":"Longitud de onda pico","grupo":"Óptica","valor":"450 - 475 nm"},{"clave":"Intensidad","grupo":"Óptica","valor":"Baja 25-35 / alta 35-55 µW/cm²/nm"},{"clave":"Vida útil LED","grupo":"Óptica","valor":"100 000 h"},{"clave":"Ruido","grupo":"Acústica","valor":"< 30 dB (sin ventilador)"},{"clave":"Cabezal / peso","grupo":"Dimensiones","valor":"75 x 340 x 210 mm; 3,6 kg"},{"clave":"Garantía del fabricante","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["LED azul de 450-475 nm con dos niveles de intensidad y variación de ±10 % en 6 horas.","Sin ventilador: ruido inferior a 30 dB y calor < 10 °C sobre el ambiente.","Pinza integrada para instalar en incubadora o cuna radiante, o carro con altura de 74 a 118 cm."],"beneficios_en":["450-475 nm blue LED with two intensity levels and ±10% variation over 6 hours.","Fan-less: noise below 30 dB and heat < 10 °C above ambient.","Built-in clamp to mount on an incubator or warmer, or a cart with height 74 to 118 cm."],"valor_es":"Una lámpara de fototerapia LED silenciosa con registro de tiempo de tratamiento, con catálogo oficial de Bistos.","valor_en":"A quiet LED phototherapy lamp with treatment-time logging, with official Bistos catalogue.","preguntas_frecuentes_es":[{"q":"¿Qué longitud de onda emite?","a":"LED azul con pico entre 450 y 475 nm."},{"q":"¿Cuánto dura el LED?","a":"Hasta 100 000 horas, según el catálogo."},{"q":"¿Cuánto pesa?","a":"3,6 kg la unidad principal; 13 kg con el carro."},{"q":"¿Dónde descargo la ficha técnica de Lámpara de Fototerapia Ref BT-400 Bistos?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Bistos (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What wavelength does it emit?","a":"Blue LED with a peak between 450 and 475 nm."},{"q":"How long does the LED last?","a":"Up to 100,000 hours, per the catalogue."},{"q":"How much does it weigh?","a":"3.6 kg the main unit; 13 kg with the cart."},{"q":"Where can I download the Phototherapy Lamp Ref BT-400 Bistos datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Bistos PDF (in English)."}],"seo_keywords_es":["fototerapia LED BT-400","lámpara de fototerapia neonatal Bistos","fototerapia luz azul","fototerapia sin ventilador","fototerapia neonatal Colombia","catálogo Bistos BT-400"],"seo_keywords_en":["BT-400 LED phototherapy","Bistos neonatal phototherapy lamp","blue light phototherapy","fan-less phototherapy","neonatal phototherapy Colombia","Bistos BT-400 catalogue"],"ficha_fabricante":{"fabricante":"Bistos","idioma":"en","url_origen":"https://expertmedicalholding.com/wp-content/uploads/2020/11/Catalog_BISTOS_BT-500-550-400_NICU.pdf","descargada":"2026-10-02"}}$j$::jsonb
