UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/bistos/catalog-bistos-bt-500-550-400-nicu.pdf',
  descripcion_larga_es = $d$La cuna de calor radiante BT-550 de Bistos (servocuna) controla la temperatura de la piel de 34 a 38 °C en modos Prewarm, Baby y Manual, con calefactor infrarrojo de 600 W y 5000 horas de vida, giro de 90°, temporizador APGAR (pitidos a 1, 5 y 10 min) y luz de examen LED de 40 W con tres niveles (> 7000 lx). Incluye bandeja de rayos X de 35 x 40 cm, pantalla TFT de 7", 6 eventos de alarma, colchón de 80 x 49 cm y opcionales de báscula, SpO₂ Masimo, inclinación y entrega de oxígeno. Mide 1890 x 1027 x 690 mm, pesa 83 kg y tiene 2 años de garantía.$d$,
  descripcion_larga_en = $d$The Bistos BT-550 radiant warmer (open care unit) controls skin temperature from 34 to 38 °C in Prewarm, Baby and Manual modes, with a 600 W infrared heater of 5000-hour life, 90° rotation, an APGAR timer (beeps at 1, 5 and 10 min) and a 40 W LED examination light with three levels (> 7000 lx). It includes a 35 x 40 cm X-ray tray, 7" TFT display, 6 alarm events, an 80 x 49 cm mattress and options for scale, Masimo SpO₂, tilting and oxygen delivery. It measures 1890 x 1027 x 690 mm, weighs 83 kg and has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"BT-550"},{"clave":"Fabricante","grupo":"Identificación","valor":"Bistos Co., Ltd."},{"clave":"Piel","grupo":"Control térmico","valor":"34 - 38 °C; modos Prewarm / Baby / Manual"},{"clave":"Calefactor","grupo":"Calefacción","valor":"Infrarrojo 600 W, 5000 h"},{"clave":"Luz de examen","grupo":"Iluminación","valor":"LED 40 W, 3 niveles, > 7000 lx"},{"clave":"Dimensiones / peso","grupo":"Dimensiones","valor":"1890 x 1027 x 690 mm; 83 kg"},{"clave":"Garantía del fabricante","grupo":"Garantía","valor":"2 años (unidad principal)"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Tres modos (Prewarm, Baby, Manual) con control servo de piel de 34 a 38 °C.","Temporizador APGAR y luz de examen LED de tres niveles (> 7000 lx).","Bandeja de rayos X y opcionales de báscula, SpO₂, inclinación y entrega de oxígeno."],"beneficios_en":["Three modes (Prewarm, Baby, Manual) with skin servo control from 34 to 38 °C.","APGAR timer and three-level LED examination light (> 7000 lx).","X-ray tray and options for scale, SpO₂, tilting and oxygen delivery."],"valor_es":"Una cuna de calor radiante con servocontrol, luz de examen y bandeja de rayos X, con catálogo oficial de Bistos.","valor_en":"A radiant warmer with servo control, examination light and X-ray tray, with official Bistos catalogue.","preguntas_frecuentes_es":[{"q":"¿Qué modos de control tiene?","a":"Prewarm, Baby y Manual; control de piel de 34 a 38 °C."},{"q":"¿Qué potencia tiene el calefactor?","a":"600 W infrarrojo, con vida de 5000 horas."},{"q":"¿Qué dimensiones y peso tiene?","a":"1890 x 1027 x 690 mm y 83 kg en versión estándar."},{"q":"¿Dónde descargo la ficha técnica de Incubadora Abierta o Servocuna Ref BT550 Bistos?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Bistos (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which control modes does it have?","a":"Prewarm, Baby and Manual; skin control from 34 to 38 °C."},{"q":"What heater power does it have?","a":"600 W infrared, with a 5000-hour life."},{"q":"What are its dimensions and weight?","a":"1890 x 1027 x 690 mm and 83 kg in the standard version."},{"q":"Where can I download the Open Incubator or Heated Crib Ref BT550 Bistos datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Bistos PDF (in English)."}],"seo_keywords_es":["cuna de calor radiante BT-550","servocuna neonatal Bistos","incubadora abierta","cuna radiante con bandeja de rayos X","cuna de calor Colombia","catálogo Bistos BT-550"],"seo_keywords_en":["BT-550 radiant warmer","Bistos neonatal open care unit","open incubator","radiant warmer with X-ray tray","radiant warmer Colombia","Bistos BT-550 catalogue"],"ficha_fabricante":{"fabricante":"Bistos","idioma":"en","url_origen":"https://expertmedicalholding.com/wp-content/uploads/2020/11/Catalog_BISTOS_BT-500-550-400_NICU.pdf","descargada":"2026-10-02"}}$j$::jsonb
