UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/mercury-medical/rdr-hyperinflationsystem.pdf',
  descripcion_larga_es = $d$El sistema de hiperinflado de Mercury Medical está formado por una bolsa de hiperinflado y una mascarilla, con manómetro opcional y válvula de alivio de presión opcional, para ventilación controlada o asistida con monitoreo simultáneo de la presión. Es de un solo paciente, ligero y libre de látex, con válvula de purga lateral estriada, puerto del paciente con giro de 360° y manómetros de hasta 60 cmH₂O integrados en el puerto. La hoja del fabricante lista versiones desde 1/2 litro, con o sin mascarilla y manómetro.$d$,
  descripcion_larga_en = $d$The Mercury Medical hyperinflation system consists of a hyperinflation bag and a face mask, with optional manometer and optional pressure relief valve, for controlled or assisted ventilation with simultaneous pressure monitoring. It is single-patient use, lightweight and latex-free, with a knurled side bleed valve, a 360° swivel patient port and manometers up to 60 cmH₂O built into the port. The manufacturer sheet lists versions from 1/2 litre, with or without mask and manometer.$d$,
  especificaciones = $j$[{"clave":"Fabricante","grupo":"Identificación","valor":"Mercury Medical"},{"clave":"Sistema","grupo":"Componentes","valor":"Bolsa de hiperinflado + mascarilla; manómetro y válvula de alivio opcionales"},{"clave":"Rango integrado","grupo":"Manómetro","valor":"Hasta 60 cmH₂O"},{"clave":"Paciente","grupo":"Uso","valor":"Un solo paciente; libre de látex"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Monitoreo de la presión entregada sin apartar la vista del paciente.","Manómetro integrado de hasta 60 cmH₂O y válvula de alivio de presión opcionales.","Un solo paciente, ligero y libre de látex, con puerto giratorio de 360°."],"beneficios_en":["Monitor delivered pressure without looking away from the patient.","Optional built-in manometer up to 60 cmH₂O and pressure relief valve.","Single-patient use, lightweight and latex-free, with 360° swivel port."],"valor_es":"Un sistema de hiperinflado de un solo paciente con monitoreo de presión en línea, con hoja oficial de Mercury Medical.","valor_en":"A single-patient hyperinflation system with in-line pressure monitoring, with official Mercury Medical sheet.","preguntas_frecuentes_es":[{"q":"¿Qué es la hiperinflación?","a":"Según el fabricante, es provocar o asistir la insuflación de los pulmones del paciente cuando necesita asistencia respiratoria, es decir, reanimar."},{"q":"¿Es reutilizable?","a":"No: es de un solo paciente y libre de látex."},{"q":"¿Qué beneficio ofrece el manómetro?","a":"Permite ver la presión entregada en línea y tener mejor sensación de la compliance pulmonar."},{"q":"¿Dónde descargo la ficha técnica de Sistema de Hiperinflado de 1 Litro Mercury?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Mercury Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"What is hyperinflation?","a":"Per the manufacturer, it is causing or assisting the inflation of the patient's lungs when breathing assistance is required, i.e. resuscitating."},{"q":"Is it reusable?","a":"No: it is single-patient use and latex-free."},{"q":"What benefit does the manometer offer?","a":"It lets you view delivered pressure in line and gives a better feel for lung compliance."},{"q":"Where can I download the Mercury 1 Liter Hyperinflation System datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Mercury Medical PDF (in English)."}],"seo_keywords_es":["sistema de hiperinflado","bolsa de hiperinflado con manómetro","Mercury Medical hiperinflado","reanimación manual con manómetro","equipo de reanimación Colombia","ficha técnica sistema de hiperinflado"],"seo_keywords_en":["hyperinflation system","hyperinflation bag with manometer","Mercury Medical hyperinflation","manual resuscitation with manometer","resuscitation equipment Colombia","hyperinflation system product sheet"],"ficha_fabricante":{"fabricante":"Mercury Medical","idioma":"en","url_origen":"https://www.mercurymed.com/wp-content/uploads/RDR_HyperinflationSystem.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'sistema-de-hiperinflado-de-1-litro-mercury';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/mercury-medical/resusa-tee-brochure.pdf',
  descripcion_larga_es = $d$El Resusa-Tee de Mercury Medical es un reanimador en T desechable para adultos y niños (pacientes de más de 10 kg), con manómetro codificado por colores de 0 a 60 cmH₂O integrado y controlador de PIP en línea con botón de anulación. No requiere equipo de capital y, al no tener bolsa que apretar, evita la fatiga de la ventilación con bolsa. Es condicional para resonancia magnética hasta 3 Tesla, según el folleto del fabricante.$d$,
  descripcion_larga_en = $d$The Mercury Medical Resusa-Tee is a disposable T-piece resuscitator for adults and children (patients above 10 kg), with a built-in colour-coded 0 to 60 cmH₂O manometer and an in-line PIP controller with override button. It requires no capital equipment and, with no bag to squeeze, avoids bag-ventilation fatigue. It is MR Conditional up to 3 Tesla, per the manufacturer brochure.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"Resusa-Tee"},{"clave":"Fabricante","grupo":"Identificación","valor":"Mercury Medical"},{"clave":"Peso","grupo":"Pacientes","valor":"Más de 10 kg (adultos y niños)"},{"clave":"Rango","grupo":"Manómetro","valor":"0 - 60 cmH₂O, codificado por colores"},{"clave":"PIP","grupo":"Control","valor":"Controlador en línea con botón de anulación"},{"clave":"Condición","grupo":"Resonancia","valor":"MR Conditional, ≤ 3 Tesla"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Reanimador en T desechable para pacientes de más de 10 kg, sin equipo de capital.","Manómetro codificado por colores de 0 a 60 cmH₂O y controlador de PIP ajustable con botón de anulación.","Sin bolsa que apretar y MR Conditional hasta 3 Tesla."],"beneficios_en":["Disposable T-piece resuscitator for patients above 10 kg, no capital equipment.","Colour-coded 0 to 60 cmH₂O manometer and adjustable PIP controller with override button.","No bag to squeeze and MR Conditional up to 3 Tesla."],"valor_es":"Un reanimador en T desechable para adultos y niños con manómetro en línea, con folleto oficial de Mercury Medical.","valor_en":"A disposable T-piece resuscitator for adults and children with in-line manometer, with official Mercury Medical brochure.","preguntas_frecuentes_es":[{"q":"¿Para qué pacientes es?","a":"Para pacientes de más de 10 kg, adultos y niños."},{"q":"¿Necesita equipo adicional?","a":"No requiere equipo de capital; es completamente desechable."},{"q":"¿Se puede usar en resonancia?","a":"Es condicional para resonancia magnética de 3,0 Tesla o menos."},{"q":"¿Dónde descargo la ficha técnica de Sistema Resusa-Tee Ref 10-51504 Mercury?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Mercury Medical (en inglés)."}],"preguntas_frecuentes_en":[{"q":"Which patients is it for?","a":"Patients above 10 kg, adults and children."},{"q":"Does it need additional equipment?","a":"It requires no capital equipment; it is completely disposable."},{"q":"Can it be used in MRI?","a":"It is MR Conditional at 3.0 Tesla or less."},{"q":"Where can I download the Resusa-Tee System Ref 10-51504 Mercury datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Mercury Medical PDF (in English)."}],"seo_keywords_es":["Resusa-Tee","reanimador en T desechable adulto y niño","reanimador en T Mercury Medical","reanimación con PEEP controlado","equipo de reanimación Colombia","folleto Resusa-Tee"],"seo_keywords_en":["Resusa-Tee","disposable adult and child T-piece resuscitator","Mercury Medical T-piece resuscitator","resuscitation with controlled PEEP","resuscitation equipment Colombia","Resusa-Tee brochure"],"ficha_fabricante":{"fabricante":"Mercury Medical","idioma":"en","url_origen":"https://www.mercurymed.com/wp-content/uploads/Resusa-Tee_Brochure-1.pdf","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'sistema-resusa-tee-ref-10-51504-mercury';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/dr-mach/59356004-drmach-lamparas-quirurgicas-es-v3-1.pdf',
  descripcion_larga_es = $d$La lámpara quirúrgica Dr. Mach LED 300MC entrega 160 000 lux a 1 m, con cuerpo luminoso de 55 cm, 36 LED con vida útil de 60 000 horas y ajuste de la temperatura de color (3750 a 4750 K) desde la zona de mango estéril. Admite cámara HD integrada y combinaciones con monitores y suspensiones de techo. La ficha del fabricante la presenta con una gama de combinaciones de soporte y configuraciones.$d$,
  descripcion_larga_en = $d$The Dr. Mach LED 300MC surgical light delivers 160,000 lux at 1 m, with a 55 cm light body, 36 LEDs with 60,000-hour life and colour temperature adjustment (3750 to 4750 K) from the sterile handle area. It supports an integrated HD camera and combinations with monitors and ceiling mounts. The manufacturer brochure presents it with a range of mounting combinations and configurations.$d$,
  especificaciones = $j$[{"clave":"Modelo","grupo":"Identificación","valor":"Mach LED 300MC"},{"clave":"Fabricante","grupo":"Identificación","valor":"Dr. Mach GmbH & Co. KG"},{"clave":"Intensidad a 1 m","grupo":"Óptica","valor":"160 000 lux"},{"clave":"Temperatura de color","grupo":"Óptica","valor":"3750 - 4750 K ajustable"},{"clave":"Cuerpo luminoso","grupo":"Dimensiones","valor":"55 cm; 36 LED"},{"clave":"LED","grupo":"Vida útil","valor":"60 000 h"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["160 000 lux a 1 metro y 36 LED con vida útil de 60 000 horas.","Temperatura de color ajustable de 3750 a 4750 K desde el mango estéril.","Cámara HD integrada opcional y diversas combinaciones de suspensión."],"beneficios_en":["160,000 lux at 1 metre and 36 LEDs with 60,000-hour life.","Colour temperature adjustable from 3750 to 4750 K from the sterile handle.","Optional integrated HD camera and various mounting combinations."],"valor_es":"Una lámpara quirúrgica LED de alta intensidad con temperatura de color ajustable, con folleto oficial de Dr. Mach.","valor_en":"A high-intensity LED surgical light with adjustable colour temperature, with official Dr. Mach brochure.","preguntas_frecuentes_es":[{"q":"¿Qué intensidad tiene?","a":"160 000 lux a 1 metro de distancia."},{"q":"¿Cuánto duran los LED?","a":"60 000 horas, según el folleto."},{"q":"¿Se puede ajustar el color de la luz?","a":"Sí, de 3750 a 4750 K desde el mango estéril."},{"q":"¿Dónde descargo la ficha técnica de Lámpara Quirúrgica Tipo LED Mach LED Ref 300MC Dr Mach?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de Dr. Mach (en español)."}],"preguntas_frecuentes_en":[{"q":"What intensity does it have?","a":"160,000 lux at 1 metre distance."},{"q":"How long do the LEDs last?","a":"60,000 hours, per the brochure."},{"q":"Can the light colour be adjusted?","a":"Yes, from 3750 to 4750 K from the sterile handle."},{"q":"Where can I download the Surgical LED Light Type Mach LED Ref 300MC Dr Mach datasheet?","a":"On this page, with the “Download datasheet” button: it is the official Dr. Mach PDF (in Spanish)."}],"seo_keywords_es":["lámpara quirúrgica LED","Dr. Mach LED 300MC","lámpara cialítica de techo","lámpara de quirófano 160000 lux","lámpara quirúrgica Colombia","folleto Dr. Mach lámparas quirúrgicas"],"seo_keywords_en":["LED surgical light","Dr. Mach LED 300MC","ceiling surgical light","160,000 lux operating room light","surgical light Colombia","Dr. Mach surgical lights brochure"],"ficha_fabricante":{"fabricante":"Dr. Mach","idioma":"es","url_origen":"https://dr-mach.de/resources/public/Downloads/59356004_DrMach_lamparas-quirurgicas_ES_V3.1.pdf","descargada":"2026-10-02"}}$j$::jsonb
